"""Render human-readable contracts from canonical JSON; no product code changes."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
model=json.loads((HERE/'model.json').read_text(encoding='utf-8'))
ucs=json.loads((HERE.parent/'use-cases.json').read_text(encoding='utf-8'))
lines=['# HAVE 유스케이스 상세 조건', '', '2026-10-28. 수정 원본은 `use-cases.json`이다. 이 문서는 `uml/export_contracts.py`로 생성한다.', '', '[유스케이스 개요](use-cases.svg) · [상태·다중도 검토](uml/state-and-multiplicity.md)', '', '현재 로컬 MVP의 계약이다. 미구현 계정/서버/서명 요구를 구현 완료로 해석하지 않는다. 모든 쓰기 결과는 원자적 저장 성공 후 확정한다.', '']
roles={item['id']:item['label'] for item in ucs['actors']}
for uc in sorted(ucs['useCases'],key=lambda item:item['id']):
 lines += [f"## {uc['id']} · {uc['name']}", '', '참여 역할: '+', '.join(roles[item] for item in uc['actors']), '', '연관 제약: '+', '.join(uc['cardinalityRefs']), '']
 for key,title in [('preconditions','사전 조건'),('postconditions','정상 결과·사후 조건'),('alternateFlows','대안·예외')]:
  lines += [f'### {title}', '']+['- '+item for item in uc[key]]+['']
(HERE.parent/'use-case-specs.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
s=model['stateSpecification']
lines=['# 상태 다이어그램과 연관 다중도 검토', '', '2026-10-28. 수정 원본은 `model.json`, 유스케이스 계약은 `../use-cases.json`이다.', '', '[검토·승인 절차 PNG](images/ST01-lifecycles.png) · [SVG](images/ST01-lifecycles.svg) · [승인 효력 SVG](images/ST02-approval.svg) · [유스케이스 상세](../use-case-specs.md)', '', '## 1. 범위 확정', '', s['scope']+'를 주 모델로 선택했다. 기준 객체는 Version이며 미승인 영역의 Review를 하위 상태로 확장한다. 작업 전체·버전 전체·승인 효력을 하나의 status enum으로 합치지 않는다.', '', '승인 이후에는 별도 Approval의 효력 변경 절차를 그린다. 다른 기기의 최신 효력·전자서명·삭제/보존 타임아웃은 현재 구현에 추가하지 않는다.', '', '## 2. 시작·종료 상태', '', '- 시작: '+s['start'], '- 종료: '+s['end'], '- 종료가 아닌 상태/사건: '+', '.join(s['notEnd']), '- 종료 기호의 뜻: '+s['finalMeaning'], '', '최종 노드는 검토·승인 절차 또는 승인 효력 변경 절차의 종료다. 객체의 삭제나 더 이상 조회할 수 없음을 뜻하지 않는다. ST01의 승인 종료 후에도 ST02의 철회가 가능하다. 철회 후 같은 버전의 재승인·철회 취소는 불가능하다.', '', '## 3. 상태와 하위 상태', '', '| 영역 | 상태 | 의미 |', '| --- | --- | --- |', '| Version 미승인 검토 | 답변 작성 중 | 미제출 답변 존재, 치명 오류·returned가 우선하지 않는 경우 |', '| Version 미승인 검토 | 검토 대기 | 세 답변 제출됨, 평가 통과 조건 미달 |', '| Version 미승인 검토 | 평가 통과 | 과제 조건 통과. 체크·메모 등을 포함한 최종 승인 조건과 별개 |', '| Version 미승인 검토 | 수정 요청 | returned 또는 현재 평가의 치명 오류 |', '| Version 절차 종료 전 | 승인 완료 | 승인·증명·감사 저장 성공, 검토 범위 고정 |', '| Approval 효력 | 미철회 승인 / 승인 철회 | 단방향 효력 변경. 후속 버전 존재와 별개 |', '', '판정 우선순위: '+s['classification'], '', '입력 슬롯 생성은 UC-01/05에서 한 번 수행한다. 답변 작성 중으로 재진입할 때마다 Review·GateResponse를 새로 생성하는 entry 액션을 넣지 않았다. 상태가 유지되는 부분 제출·체크 보완·조회는 새 객체 수를 늘리지 않는다.', '', '## 4. 이벤트·조건·액션', '', '화살표는 `이벤트 [조건] / 액션`으로 읽는다. 그림의 T 번호를 아래 행과 연결한다. 모든 호출에 역할/대상/입력 검증과 저장 성공이라는 공통 전제가 있다.', '']
for key,value in s['symbols'].items():lines.append(f'- **{key}**: {value}')
lines += ['', '| ID | 출발 → 도착 | 이벤트 | 조건 | 액션 |', '| --- | --- | --- | --- | --- |']
for t in s['transitions']:
 esc=lambda x:x.replace('|','/').replace('\n',' ')
 lines.append('| '+' | '.join(esc(x) for x in [t['id'],t['source']+' → '+t['target'],t['event'],t['guard'],t['action']])+' |')
lines += ['', 'T15의 재판정: 기여 추가는 현재 평가를 모두 지우므로 P는 거짓이다. returned가 남아 있으면 수정 요청, returned가 없고 세 답변이 제출되어 있으면 검토 대기, 나머지는 답변 작성 중이다. 기존 제출 여부와 returned를 임의로 초기화하지 않는다. 그림의 T12/T15 화살표는 실제 도착이 작성 중인 경우만 뜻한다.', '', '자기 전이: 부분 제출, 현재 평가/근거 보완, 체크·메모 변경, returned가 유지되는 기여 연결 등은 판정 결과가 같으면 같은 상태다. 수정 요청 상태에서 세 답변이 제출되어 있고 사유가 있으면 다시 수정 요청할 수도 있으며, 회차만 추가되고 상태는 유지된다.', '', '거부: 미제출 답변 평가, 승인된 범위 변경, 사유 없는 수정/철회, 중복 승인, 모두 중복인 기여, 상한 초과 등은 성공 전이가 아니다. '+s['persistence'], '', '후속 버전 생성은 새로운 상태기계 인스턴스의 시작이다. 이전 버전의 검토나 승인을 초기 상태로 되돌리는 전이를 그리지 않는다.', '', '## 5. 다중도 감사와 유스케이스 반영', '', '관계 `A "m" -- "n" B`에서 A 하나가 참조하는 B 수는 n, B 하나가 참조하는 A 수는 m이다. 아래 표는 양쪽 끝을 함께 확인한다. `*`는 구조적 다중도이며 현재 스키마의 개수 상한은 별도 제약으로 적는다.', '', '| ID | 연관 | 판정 | 성립 조건·범위 | 관련 UC |', '| --- | --- | --- | --- | --- |']
for r in model['cardinalityAudit']:
 lines.append(f"| {r['id']} | {r['source']} `{r['sourceMultiplicity']}` -- `{r['targetMultiplicity']}` {r['target']} | {r['result']} | {r['condition']} | {', '.join(r['useCases'])} |")
lines += ['', '수정한 구조: Version–AuditEvent 연관을 추가했다. 기존 Work–AuditEvent 연관은 작업 소속을 나타내므로 함께 유지한다. 사건의 대상 버전은 그 작업 안에 있어야 한다.', '', '보완한 해석: Contribution은 전역 원본 기록이 아니라 버전별 사본/연결 값이다. `/key=(versionId,recordId)`는 소속 버전에서 유도하는 개념 식별자이며 실제 JSON에 새 versionId 필드를 요구한 것이 아니다. 같은 ID를 다른 버전에 가져오는 것은 허용하지만 같은 버전에서 중복 추가는 거부한다.', '', 'ReviewRound는 과거 값 스냅샷이고 Evaluation은 현재 슬롯의 평가다. 여러 회차가 존재해도 현재 평가가 답변 하나에 여러 개 붙는 것이 아니다. 원본 기록과 사본을 전역 엔터티로 관리하려는 후속 요구가 생기면 연결 클래스를 별도 설계한다.', '', 'Approval–Receipt 1:1은 현재 로컬 저장의 payload 모델이다. 운영 서비스에서 승인 결정 후 비동기 서명 영수증이 준비되기 전 0..1인 설계는 다른 범위이며 섞지 않는다.', '', '## 6. 강의 근거와 검증', '', '보조 PDF 11쪽의 상태/이벤트/액션, 12~13쪽의 가드와 종료 예, 14쪽의 복합 상태, 15쪽의 독립 병행 영역, 16쪽의 다섯 작성 단계를 적용했다. 사례의 재승인·기간 경과 종료는 HAVE의 요구로 복사하지 않았다. 현재 예제는 인과적으로 이어지는 단계이므로 임의의 병렬 지역을 추가하지 않았다.', '', '코드 근거: `prototype/dist/domain.js`의 `validateDatabase`, `gatesPassed`, `status`, `validateTransition`; `app.js`의 `confirmContributions`, `returnForm`, `approve`, `revokeForm`, `transaction`.', '', '재생성: `python docs/modeling/optimized/uml/export_contracts.py`. 모델 감사: `node docs/modeling/optimized/uml/audit_constraints.cjs`. 현재 4개 관련 그림만 생성: `node docs/modeling/optimized/uml/render.cjs C01-domain C02-review ST01-lifecycles ST02-approval`.', '']
(HERE/'state-and-multiplicity.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Generated UC specifications and state/multiplicity review from canonical JSON.')
